from collections import deque
from typing import List

class Solution:
    def minOperations(self, front: List[int], back: List[int]) -> int:
        n = len(front)
        start_perm = tuple(range(n))
        start_parity = 0

        def is_goal(perm, parity):
            visible = []
            for card in perm:
                if (parity >> card) & 1:
                    visible.append(back[card])
                else:
                    visible.append(front[card])

            for i in range(1, n):
                if visible[i] < visible[i-1]:
                    return False
            return True

        visited = set()
        queue = deque([(start_perm, start_parity, 0)])
        visited.add((start_perm, start_parity))

        while queue:
            perm, parity, steps = queue.popleft()

            if is_goal(perm, parity):
                return steps

            for i in range(n-1):
                perm_list = list(perm)
                perm_list[i], perm_list[i+1] = perm_list[i+1], perm_list[i]

                new_parity = parity ^ (1 << perm[i]) ^ (1 << perm[i+1])
                new_state = (tuple(perm_list), new_parity)

                if new_state not in visited:
                    visited.add(new_state)
                    queue.append((tuple(perm_list), new_parity, steps+1))

        return -1
